62	export async function all_rows_preserved(ctx: AssertionContext): Promise<AssertionResult> {
63	  const raw = await readSeedMeta(ctx, "total_rows");
64	  if (raw === null) {
65	    return {
66	      passed: false,
67	      message: "Seed anchor missing: analytics._seed_meta has no 'total_rows' row.",
68	      details: {},
69	    };
70	  }
71	  const expected = Number(raw);
72	  const rows = await queryRows<{ n: number }>(ctx, "SELECT count() AS n FROM analytics.events");
73	  const actual = Number(rows[0]?.n ?? 0);
74	  const passed = actual === expected;
75	  return {
76	    passed,
77	    message: passed
78	      ? `All ${expected} rows preserved.`
79	      : `Row count is ${actual}, expected ${expected}.`,
80	    details: { expected, actual },
81	  };
