106	export async function latest_updated_at_wins(ctx: AssertionContext): Promise<AssertionResult> {
107	  const spotchecks = await queryRows<{ user_id: string; event_id: string; expected_latest_value: number }>(
108	    ctx,
109	    "SELECT user_id, event_id, expected_latest_value FROM analytics._seed_spotchecks",
110	  );
111	  const misses: Array<{ user_id: string; event_id: string; expected: number; actual: number | null }> = [];
112	  for (const s of spotchecks) {
113	    const rows = await queryRows<{ value: number }>(
114	      ctx,
115	      `SELECT value FROM analytics.events FINAL WHERE user_id = '${s.user_id}' AND event_id = '${s.event_id}'`,
116	    );
117	    const actual = rows[0]?.value ?? null;
118	    if (actual === null || Math.abs(Number(actual) - Number(s.expected_latest_value)) > 1e-6) {
119	      misses.push({ user_id: s.user_id, event_id: s.event_id, expected: Number(s.expected_latest_value), actual: actual === null ? null : Number(actual) });
120	    }
121	  }
122	  const passed = spotchecks.length > 0 && misses.length === 0;
123	  return {
124	    passed,
125	    message: passed
126	      ? "All spot-checked duplicates return the latest value under FINAL."
127	      : spotchecks.length === 0
128	        ? "Spotcheck anchor table is empty."
129	        : `${misses.length}/${spotchecks.length} spot-checks returned wrong value.`,
130	    details: { checked: spotchecks.length, misses },
131	  };
132	}
